insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('es-hod-eam-gschdraad', 'Es hod eam gschdraad!', '', '', '', '', 'Es hat ihn gestreut!', '[{"kategorie": "", "text": "Er ist zu Sturz gekommen!  2. Es hat ihn hingehauen!  3. Es hat ihn niedergestreckt!"}]'::jsonb, ''),
  ('es-woa-ned-aufgschdraad-und-i-woa-augschdraad-do-hods-mi-higschdraad', 'Es woa ned aufgschdraad und I woa augschdraad, do hods mi higschdraad!', '', '', '', '', 'Es war nicht aufgestreut und ich war angestreut, da hat es mich hingestreut!', '[{"kategorie": "", "text": "Der Gehweg war nicht gestreut, ich war angetrunken, da bin ich hingefallen!  2. Es war kein Splitt gestreut, ich war alkoholisiert, da hat es mich niedergestreckt!"}]'::jsonb, ''),
  ('is-ana-augschdraad-daunn-ghead-hoid-mea-gschdraad-sunst-is-a-heagschdraad', 'Is ana augschdraad, daunn ghead hoid mea gschdraad, sunst is a heagschdraad!', '', '', '', '', 'Ist jemand angestreut, dann gehört halt mehr gestreut, sonst ist er hergestreut!', '[{"kategorie": "", "text": "Ist jemand angetrunken, dann muss der Gehweg halt besser gestreut werden, sonst ist der Betrunkene [[aufgeblattelt]] [blamiert]!  2. Ist jemand angetrunken, dann muss halt mehr Streugut ausgebracht werden, sonst wird der Betrunkene noch zum Gespött der Leute!"}]'::jsonb, ''),
  ('do-woara-uandlich-heagschdraad', 'Do woara uandlich heagschdraad!', '', '', '', '', 'Da war er ordentlich hergestreut!', '[{"kategorie": "", "text": "Da war er gehörig blamiert!  2. Da war er ordentlich bloßgestellt!"}]'::jsonb, ''),
  ('wiara-ia-des-gsogt-hod-hods-uandlich-gschdraumpfd', 'Wiara ia des gsogt hod, hods uandlich gschdraumpfd!', '', '', '', '', 'Wie er ihr das gesagt hat, hat sie ordentlich gestrampft!', '[{"kategorie": "", "text": "Als er ihr das sagte, hat sie vehement protestiert!  2. Als er ihr das sagte, hat sie sich heftig zur Wehr gesetzt!"}]'::jsonb, ''),
  ('a-schdrendl-unblaachda', 'a Schdrendl Unblaachda', '', '', '', '', 'ein Strendel Ungebleichter', '[{"kategorie": "wörtlich", "text": "\"ein halbes Seitel Branntwein\""}, {"kategorie": "", "text": "ein großes Glas Schnaps (ca. 0,16 Liter)"}]'::jsonb, ''),
  ('schdraasaund-drauf', 'Schdraasaund drauf!', '', '', '', '', 'Streusand drauf!', '[{"kategorie": "wörtlich", "text": "\"Deckel drauf!\"  2. Erledigt und vergessen!  3. Das ist gegessen!"}]'::jsonb, ''),
  ('aum-schdrich-gee', 'aum Schdrich gee', '', '', '', '', 'auf den Strich gehen', '[{"kategorie": "wörtlich", "text": "\"der Prostitution nachgehen\""}, {"kategorie": "", "text": "[[anschaffen]] gehen, [[telachen]], [[strasseln]] (Erklärung: um die Jahrhundertwende durften \"Straßendirnen\"  in Wien ihre Dienste nur innerhalb eines bestimmten Bereiches („hinter dem Strich“) am Bordsteinrand anbieten, um normale Passanten nur ja nicht zu behindern [daher auch die Bezeichnung „[[Bordsteinschwalben]]“ für \"Prostituierte vom Straßenstrich\"])"}]'::jsonb, ''),
  ('wem-gengan-schdrich-gee', 'wem gengan Schdrich gee', '', '', '', '', 'jemandem gegen den Strich gehen', '[{"kategorie": "wörtlich", "text": "\"jemandem gegen die Maserung schleifen\" (Tischlerhandwerk)"}, {"kategorie": "", "text": "jemandem widerstreben, nicht passen, zuwider sein"}, {"kategorie": "", "text": "jemanden ärgern, stören, irrtieren"}]'::jsonb, ''),
  ('des-geed-ma-gengan-schdrich', 'Des geed ma gengan Schdrich!', '', '', '', '', 'Das geht mir gegen den Strich!', '[{"kategorie": "", "text": "Das passt mir überhaupt nicht!  2. Das ist überhaupt nicht in meinem Sinne!"}]'::jsonb, ''),
