  ('gimma-no-a-schdickl', 'Gimma no a Schdickl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gib mir noch ein Stückchen!', '[{"kategorie": "wörtlich", "text": "\"Gib mir noch ein kleines Stück!\"  2. Reich mir noch ein Scheibchen!  3. Gib mir noch ein Häppchen!"}]'::jsonb, ''),
  ('olle-schdickln-schbueuen', 'olle Schdickln schbüün', '', '', '', 'Wiener Sprüche, die sitzen!', 'alle Stückeln spielen', '[{"kategorie": "wörtlich", "text": "\"alle Stückchen spielen\""}, {"kategorie": "", "text": "keine Wünsche offen lassen"}, {"kategorie": "", "text": "in allen Facetten glänzen"}, {"kategorie": "", "text": "unübertroffen, herausragend sein"}]'::jsonb, ''),
  ('mei-neichs-eisn-schbueued-olle-schdickln', 'Mei neichs Eisn schbüüd olle Schdickln!', '', '', '', 'Wiener Mechaniker-Slang', 'Mein neues Eisen spielt alle Stückerln!', '[{"kategorie": "wörtlich", "text": "\"Mein neues Motorrad spielt alle Stückerln!\"  2. Mein neuer Feuerstuhl lässt keine Wünsche offen!  3. Meine neue Maschine haut richtig rein und hat alles, was geht!"}]'::jsonb, 'olle Schdickln schbüün'),
  ('soiche-schdickln-bitt-i-ma-aus-in-mein-haus', 'Soiche Schdickln bitt I ma aus in mein Haus!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Solche Stückeln bitte ich mir aus in meinem Haus!', '[{"kategorie": "wörtlich", "text": "Solche Schmierenstücke verbitte ich mir in meinem Haus!  2. Solche Frechheiten dulde ich nicht in meinem Haus!  3. Solche Unarten haben in meinem Haus keinen Platz!"}]'::jsonb, ''),
  ('wos-schdudian-lossn', 'wos schdudian lossn', '', '', '', '', 'etwas studieren lassen', '[{"kategorie": "wörtlich", "text": "\"etwas zwecks Verpfändung genau ansehen lassen\", \"etwas verpfänden lassen\""}, {"kategorie": "", "text": "etwas schätzen lassen, etwas zwecks Verpfändung inspizieren lassen, einen Pfandwert für etwas feststellen lassen"}]'::jsonb, ''),
  ('i-schdudia-goa-ned-easchd-driiwa-nooch-wos-muagn-sei-kennd', 'I schdudia goa ned easchd driiwa nooch, wos muagn sei kennd!', '', '', '', '', 'Ich studiere gar nicht erst darüber nach, was morgen sein könnte!', '[{"kategorie": "", "text": "Ich denke gar nicht erst darüber nach, was morgen sein könnte!  2. Ich verschwende keinen Gedanken an morgen!"}]'::jsonb, ''),
