  ('kremsa-senf', 'Kremsa Senf', '', '', '', '', 'Kremser Senf', '[{"kategorie": "wörtlich", "text": "\"Senf aus Krems an der Donau\""}, {"kategorie": "", "text": "süßer Senf, [[Siassa]] (Süßsenf aus grob gemahlenen gelben und braunen Senfsamen, etwas Zucker, unvergorenem Weinmost und Weinessig, ursprünglich aus der Region Krems)"}, {"kategorie": "Würstelstandjargon", "text": "[[Griasslada]], [[Dipflada]], [[Gschbiebana]], [[Gschissana]]"}]'::jsonb, ''),
