  ('oe3', 'Ö3', '', '', '', '', 'Ö3', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"drittes Radioprogramm des österreichischen Rundfunks\" ([[ORF]])"}, {"kategorie": "", "text": "Österreichs bundesweit ausgestrahlter Kultur- und Informationssender, der seit dem Umzug aus Heiligenstadt 2022 großteils aus dem ORF Mediencampus am [[Küniglberg]] sendet."}]'::jsonb, ''),
  ('oe1', 'Ö1', '', '', '', '', 'Ö1', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"erstes Radioprogramm des österreichischen Rundfunks\" ([[ORF]])"}, {"kategorie": "", "text": "Österreichs bundesweit ausgestrahlter Radiosender, der seit dem Umzug aus dem Funkhaus Wien 2022 großteils aus dem ORF Mediencampus am [[Küniglberg]] sendet"}, {"kategorie": "", "text": "Radiosender, der vor allem aktuelle Musik, Nachrichten und Unterhaltung bietet."}]'::jsonb, ''),
  ('oe2', 'Ö2', '', '', '', '', 'Ö2', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"zweites Radioprogramm des österreichischen Rundfunks\" ([[ORF]])"}, {"kategorie": "", "text": "Sammelbezeichnung für Österreichs neun Bundesländer-Regionalsender (vormals \"Ö-Regional\")"}]'::jsonb, ''),
  ('fm4', 'FM4', '', '', '', '', 'FM4', '[{"kategorie": "allg.", "text": "\"Jugendkulturradiosender des Österreichischen Rundfunks\" ([[ORF]]), der seit dem Umzug aus dem Funkhaus Wien 2022 großteils aus dem ORF Mediencampus am [[Küniglberg]] sendet"}, {"kategorie": "", "text": "Der Sender weist einen hohen Wortanteil auf, arbeitet eng mit der österreichischen Musiklandschaft zusammen, trifft eine heterogene Musikauswahl abseits des Chart-Mainstreams der Formatradios und sendet zweisprachig"}, {"kategorie": "", "text": "FM4 ging am 16. Januar 1995 auf Sendung und entstand ursprünglich aus einer Sendeschiene des ORF-Radiosenders [[Ö]]3, die als Alternative zum Mainstreamprogramm konzipiert war. Mit dem Start von FM4 wurde diese alternative Ausrichtung zu einem eigenständigen, 24-Stunden-Programm ausgeweitet"}, {"kategorie": "", "text": "FM4 bietet eine breite Palette an Musikgenres, die von Indie, Alternative, Electro und Hip-Hop bis hin zu Punk, Metal und Reggae reicht. Die Musikauswahl wird häufig von Musikredakteuren kuratiert, die Wert auf neue und innovative Musik legen, die oft jenseits des Mainstreams liegt. Neben Musik sendet FM4 auch kulturelle Beiträge, aktuelle Nachrichten und Reportagen sowie satirische Inhalte."}]'::jsonb, ''),
  ('orf-1', 'ORF 1', '', '', '', '', 'ORF 1', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Österreichischer Rundfunk, 1. Fernsehkanal\""}, {"kategorie": "", "text": "Fernsehsender mit einem Programmangebot, das Filme, Serien, Sport und Unterhaltung umfasst"}]'::jsonb, ''),
  ('orf-2', 'ORF 2', '', '', '', '', 'ORF 2', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Österreichischer Rundfunk, 2. Fernsehkanal\""}, {"kategorie": "", "text": "Fernsehsender mit einem stärkeren Fokus auf Information, Nachrichten, Kultur und Regionalprogramme"}]'::jsonb, ''),
  ('orf-iii', 'ORF III', '', '', '', '', 'ORF III', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Österreichischer Rundfunk, 3. Fernsehkanal\""}, {"kategorie": "", "text": "Kultur- und Informationskanal, der sich auf Dokumentationen, Diskussionen und kulturelle Inhalte konzentriert"}]'::jsonb, ''),
  ('orf-sport', 'ORF Sport +', '', '', '', '', 'ORF Sport +', '[{"kategorie": "wörtlich, Abkürzung für", "text": "\"Österreichischer Rundfunk, 4. Fernsehkanal\""}, {"kategorie": "", "text": "Fernsehkanal, der sich auf Sportberichterstattung und Live-Übertragungen spezialisiert hat"}]'::jsonb, ''),
  ('oe24-tv', 'Ö24 TV', '', '', '', '', 'Ö24 TV', '[{"kategorie": "wörtlich", "text": "\"Österreichs privater Fernseh-Nachrichtensender mit Sitz im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), der 24 Stunden täglich sendet\""}, {"kategorie": "", "text": "Fernsehsender und Online-Nachrichtenportal, das zu der von Wolfgang Fellner gegründeten Mediengruppe Österreich gehört, einem der einflussreichsten privaten Medienunternehmen des Landes"}, {"kategorie": "", "text": "Ö24 ist bekannt für seine schnelle und umfassende Berichterstattung über aktuelle Ereignisse in Österreich und der Welt. Das Portal hat eine starke Ausrichtung auf Boulevardjournalismus und bietet neben Nachrichten auch Klatsch und Tratsch, Sensationsmeldungen und unterhaltsame Inhalte. Dieser Fokus hat Ö24 eine breite Zuseherschaft beschert, aber auch Kritik wegen seiner teilweise reißerischen Berichterstattung eingebracht."}]'::jsonb, ''),
  ('si-de-oeoelung-geem', 'si de Öölung geem', '', '', '', '', 'sich die Ölung geben', '[{"kategorie": "wörtlich", "text": "\"sich die letzte Ölung geben\" (Sakrament der Krankensalbung)"}, {"kategorie": "scherzhaft für", "text": "sich einen Vollrausch antrinken, sich ein [[Kapuzerl]] umhängen, sich in die [[Wellen]] hauen"}, {"kategorie": "", "text": "[[sich]] anröhreln, [[sich]] zuschütten, [[sich]] zubetonieren"}]'::jsonb, ''),
