  ('du-reedsd-wiara-poowal-dea-sei-ewigs-spruechal-aufsoogd', 'Du reedsd wiara Poowal, dea sei ewigs Sprüchal aufsoogd!', '', '', '', '', 'Du redest wie ein Papagei, der sein ewiges Sprüchlein aufsagt!', '[{"kategorie": "", "text": "Du redest wie ein Papagei immer dasselbe!  2. Du wiederholst dich ständig wie ein hängengebliebener Plattenspieler!"}]'::jsonb, ''),
