  ('nimm-da-dein-batil', 'Nimm da dein Batil!', '', '', '', '', 'Nimm dir deinen Partikel!', '[{"kategorie": "", "text": "Nimm dir deinen Anteil!  2. Nimm dir, was dir zusteht!"}]'::jsonb, ''),
  ('i-foa-imma-mein-batikl', 'I foa imma mein Batikl!', '', '', '', '', 'Ich fahre immer meinen Partikel!', '[{"kategorie": "", "text": "Ich fahre immer meine gewohnte Geschwindigkeit"}, {"kategorie": "", "text": "Ich fahre immer mit geziemender Geschwindigkeit!"}]'::jsonb, ''),
