  ('auf-da-pass-sei', 'auf da Pass sei', '', '', '', '', 'auf der Pass sein', '[{"kategorie": "wörtlich", "text": "\"auf der Hut sein\" (vom mittelhochdeutschen \"auf etwas passen\"=\"aufpassen)"}, {"kategorie": "", "text": "wachsam sein, auf der Lauer sein"}]'::jsonb, ''),
  ('passd-ollas', 'Passd ollas?', '', '', '', '', 'Passt alles?', '[{"kategorie": "wörtlich", "text": "Alles in Ordnung?  2. Rundum zufrieden? (typische Frage eines Wiener Kellners [[[Ober]]] an seine Gäste)"}]'::jsonb, 'Passd scho!'),
  ('passd-scho', 'Passd scho!', '', '', '', '', 'Passt schon!', '[{"kategorie": "wörtlich", "text": "Alles gut!  2. Alles okay! (typische Antwort der Gäste auf des Kellners Frage: [[Passd ollas?]])"}]'::jsonb, ''),
  ('passd-ee', 'Passd ee!', '', '', '', '', 'Passt eh!', '[{"kategorie": "wörtlich", "text": "Alles gut!  2. Alles okay! (typische Antwort der Gäste auf des Kellners Frage: [[Passd ollas?]])"}]'::jsonb, ''),
  ('auf-wem-passn', 'auf wem passn', '', '', '', '', 'auf jemanden passen', '[{"kategorie": "wörtlich", "text": "\"jemanden an einem bestimmten Ort erwarten\""}, {"kategorie": "", "text": "jemanden abpassen, auf jemanden lauern"}]'::jsonb, ''),
  ('passd-da-des', 'Passd da des?', '', '', '', '', 'Passt dir das?', '[{"kategorie": "", "text": "Ist dir das recht?  2. Geht das für dich in Ordnung?"}]'::jsonb, ''),
  ('des-daeaedada-so-passn', 'Des däädada so passn!', '', '', '', '', 'Das täte dir so passen!', '[{"kategorie": "", "text": "Das hättest du wohl gerne!  2. So weit kommt''s noch!  3. So siehst du aus!  4. Sonst noch Wünsche?  5. Nicht mit mir!"}]'::jsonb, ''),
  ('ned-reesdn-du-hoeoed-nua-auschwitzn-waunn-d-zwiifaen-braun-wean-hostas-vageigd', 'Ned reesdn, du Hööd, nua auschwitzn! Waunn d''Zwiifän braun wean, hostas vageigd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Nicht rösten, du Held, nur anschwitzen! Wenn die Zwiebel braun werden, hast du''s vergeigt!', '[{"kategorie": "wörtlich", "text": "\"Anschwitzen, du Held, nicht verbrennen! Wenn die Zwiebel braun statt glasig werden, hast du''s verhaut!\"  2. Wenn’s kracht und zischt, passt was nicht. Anschwitzen heißt: flüstern im Topf, nicht Heavy Metal!  3. Du sollst die Zwiebel glasig machen - die brauchen Liebe, keine Feuerbestattung!"}]'::jsonb, ''),
  ('ned-reesdn-du-hoeoed-nua-aupassian-waunn-d-zwiifaen-braun-wean-hostas-vageigd', 'Ned reesdn, du Hööd, nua aupassian! Waunn d''Zwiifän braun wean, hostas vageigd!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Nicht rösten, du Held, nur anpassieren! Wenn die Zwiebel braun werden, hast du''s vergeigt!', '[{"kategorie": "wörtlich", "text": "\"Anpassieren, du Held, nicht verbrennen! Wenn die Zwiebel braun statt glasig werden, hast du''s verhaut!\"  2. Wenn’s kracht und zischt, passt was nicht. Anpassieren heißt: flüstern im Topf, nicht Heavy Metal!  3. Du sollst die Zwiebel glasig machen - die brauchen Liebe, keine Feuerbestattung!"}]'::jsonb, ''),
  ('passiad-do-boid-wos', 'Passiad do boid wos?', '', '', '', 'Wiener Sprüche, die sitzen!', 'Passiert da bald was?', '[{"kategorie": "wörtlich", "text": "\"Tut sich da bald etwas?\"  2. \"Geht da bald etwas weiter?\"  3. \"Wann passiert denn da endlich was?\""}]'::jsonb, ''),
  ('flotte-lotte', 'Flotte Lotte', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Flotte Lotte', '[{"kategorie": "wörtlich", "text": "\"Flotte Lotte\" (eingetragener Markenname, registriert in den 1930er-Jahren vom deutschen Hersteller „Gebrüder Graef“, ursprünglich unter der Bezeichnung „Passiergerät Lotte“ bekannt)"}, {"kategorie": "techn.", "text": "\"Passiermaschine\" (\"handbetriebenes Küchengerät zum [[Passieren]] von Früchten, Gemüse oder anderen Lebensmitteln), \"Passiermühle\", \"Püriermühle\", \"Passiergerät\""}]'::jsonb, 'De Omi hod ollas duach de Flotte Lotte druckd - Paradeisa, Eadäpfän, sogoa Rabaaba!'),
  ('de-omi-hod-ollas-duach-de-flotte-lotte-druckd-paradeisa-eadaepfaen-sogoa-rabaaba', 'De Omi hod ollas duach de Flotte Lotte druckd - Paradeisa, Eadäpfän, sogoa Rabaaba!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Oma hat alles durch die Flotte Lotte gedrückt – Paradeiser, Erdäpfeln, sogar Rhabarber!', '[{"kategorie": "wörtlich", "text": "\"Oma hat noch alles durch die Flotte Lotte gedrückt – Tomaten, Kartoffeln, sogar Rhabarber!\"  2. Ob Tomaten, Erdäpfel oder Rhabarber – bei Oma landete alles in der Flotten Lotte!  3. Oma bearbeitete alles mit ihrer alten Flotten Lotte – ein leises Quietschen, ein gleichmäßiges Drehen, und am Ende lag alles weich und fein passiert im Topf!"}]'::jsonb, 'Flotte Lotte'),
  ('a-patenta-buasch', 'A patenta Buasch', '', '', '', '', 'Ein patenter Bursche!', '[{"kategorie": "", "text": "Ein tüchtiger Bursche!  2. Ein feiner Kerl!  3. Ein beherzter junger Mann!"}]'::jsonb, ''),
  ('a-patents-madl', 'A patents Madl', '', '', '', '', 'Ein patentes Mädchen!', '[{"kategorie": "", "text": "Ein tüchtiges Mädchen!  2. Ein nettes, umgängliches Mädchen, das selbst zupackt!  3. Ein handfestes Mädchen!  4. Eine beherzte junge Dame!"}]'::jsonb, ''),
  ('dia-ghead-a-patentwaatschn-dass-da-s-endlich-leansd', 'Dia ghead a Patentwaatschn, dass da''s endlich leansd!', '', '', '', 'Wiener Gaunersprache', 'Dir gehört eine Patentwatschen, damit du es endlich lernst!', '[{"kategorie": "wörtlich", "text": "\"Dir gehört eine saftige Ohrfeige, damit du deine Lektion endlich lernst!\"  2. Du brauchst eine ordentliche Watsche, damit du endlich kapierst, was Sache ist!  3. Eine saftige Watsche ist wohl das Einzige, was dir noch was beibringt!"}]'::jsonb, ''),
  ('owa-hallo', 'Owa hallo!', '', '', '', '', 'Aber hallo!', '[{"kategorie": "Ausdruck der Bekräftigung", "text": "\"Ganz recht!\", \"Absolut!\", \"Stimmt genau!\""}, {"kategorie": "Ausdruck des Widerspruchs", "text": "\"Oh doch!\", \"Aber sicher doch!\", \"Das sehe ich anders!\""}]'::jsonb, ''),
  ('nau-bumm-dea-hod-mi-lackiad', 'Nau bumm, dea hod mi lackiad!', '', '', '', '', 'Na bumm, der hat mich lackiert!', '[{"kategorie": "", "text": "Oh Mann, hat der mich hintergangen!  2. Himmel noch mal, hat der mich beschissen!"}]'::jsonb, ''),
  ('boodschhandi-zsaumm', 'Boodschhandi zsaumm!', '', '', '', '', 'Patschhandi zusammen!', '[{"kategorie": "wörtlich, Kindersprache", "text": "\"Klatsch die [[Patschhändchen]] zusammen\" (Aufforderung an ein Kleinkind, die Hände zusammenzuklatschen)"}, {"kategorie": "", "text": "Klatsch die Händchen!  3. Klatsch die Pfötchen!"}]'::jsonb, ''),
  ('kiawis-patzln', 'Kiawis patzln', '', '', '', '', 'Kürbis patzeln', '[{"kategorie": "wörtlich", "text": "\"die Kürbiskerne mit den Fingern aus dem Kürbis herauslösen\""}, {"kategorie": "", "text": "\"Kürbiskerne ernten\" (man halbierte einst die Kürbisse mit einem Beil und schabte dann in mühevollster Kleinarbeit die Kürbiskerne mit den Fingern heraus)"}]'::jsonb, ''),
  ('heid-schbritzlds-nua-owa-gestan-hods-gwaschld', 'Heid schbritzlds nua, owa gestan hods gwaschld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Heute spritzelt es nur, aber gestern hat es gewaschelt!', '[{"kategorie": "wörtlich", "text": "\"Heute tröpfelt es nur, aber gestern hat es in Strömen geregnet!\"  2. Heute nieselt es nur, aber gestern hat es wie aus Kübeln geschüttet!  3. Heute kommen nur ein paar Tropfen runter, aber gestern hättest ohne Boot nicht heimgefunden!"}]'::jsonb, ''),
  ('scheiss-au-paula', 'Scheiss au, Paula!', '', '', '', '', 'Scheiß an, Paula!', '[{"kategorie": "wörtlich", "text": "\"Scheiß an, die Monatsblutung!\" (\"Paula\" = verhüllend für \"Menstruation\""}, {"kategorie": "allgemeiner Ausruf des Erstaunens bzw. Entsetzens", "text": "2. Herrje!  Verflixt!  Zum Teufel noch mal!  Ach du Schande!  [[Marantana]]!"}]'::jsonb, ''),
  ('paula-tant', 'Paula-Tant', '', '', '', '', 'die Tante Paula', '[{"kategorie": "wörtlich, scherzhaft verhüllend für", "text": "Monatsblutung"}, {"kategorie": "allg.", "text": "Menstruation, Periode, \"Tage\", [[rote]] Tante, [[Resi-Tant]]"}]'::jsonb, 'Scheiss au, Paula!'),
  ('de-aufdraade-pauli-banaan-haum', 'de aufdraade Pauli-Banaan haum', '', '', '', '', 'die hochgedrehte Pauli-Banane haben', '[{"kategorie": "wörtlich", "text": "\"nicht zum Zug kommen\" (eigentlich: \"wegen Regelblutung der Partnerin nicht zum Schuss kommen\")"}, {"kategorie": "", "text": "das Nachsehen haben, leer ausgehen, außen vor bleiben"}]'::jsonb, ''),
  ('es-pech-aum-oasch-haum', 'es Pech aum Oasch haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'das Pech am Arsch haben', '[{"kategorie": "wörtlich", "text": "\"das Baumharz am Arsch kleben haben\" (von [[Pech]]=\"Baumharz\")"}, {"kategorie": "scherzhaft für", "text": "den Arsch nicht hochbekommen, am Sessel festkleben, (vom Wirtshaustisch, etc.) nicht wegkommen"}]'::jsonb, 'Dea hods Pech aum Oasch - den miass ma mit da Schbochtl von da Wiatshausbaunk krotzn!'),
  ('dea-hods-pech-aum-oasch-den-miass-ma-mit-da-schbochtl-von-da-wiatshausbaunk-krotzn', 'Dea hods Pech aum Oasch - den miass ma mit da Schbochtl von da Wiatshausbaunk krotzn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der hat das Pech am Arsch - den müssen wir mit der Spachtel von der Wirtshausbank kratzen!', '[{"kategorie": "wörtlich", "text": "\"Der hat das Baumharz am Arsch kleben - den müssen wir mit der Spachtel von der Wirtshausbank kratzen!\"  2. Der kriegt den Hintern nicht hoch und klebt an der Wirtshausbank fest, als hätte er Pech am Arsch!  3. Der hat soviel Pech am Arsch, dass er mit der Wirtshausbank schon festgewachsen ist!"}]'::jsonb, 'es Pech aum Oasch haum'),
  ('glaubst-i-bin-da-pforra-von-penzing', 'Glaubst I bin da Pforra von Penzing?', '', '', '', '', 'Glaubst du, ich bin der Pfarrer von Penzing?', '[{"kategorie": "wörtlich, Scherzfrage", "text": "Glaubst du, ich bin der Pfarrer aus dem 14. Bezirk?  2. (Kartenspielerjargon, scherzhaft für): Warum gibst du mir die Karten zum Mischen, wenn ich gar nicht dran bin?  3. Warum drückst du mir die Karten in die Hand, wenn ein ganz anderer zum Mischen dran ist?"}]'::jsonb, ''),
  ('i-woad-no-imma-auf-mei-peensi', 'I woad no imma auf mei Peensi!', '', '', '', '', 'Ich warte noch immer auf meine Pensi!', '[{"kategorie": "", "text": "Ich warte noch immer auf die Auszahlung meiner Pension!  2. Ich warte noch immer darauf, dass meine Rente endlich eintrifft!"}]'::jsonb, ''),
  ('gee-pepal-plausch-ned', 'Gee, Pepal, plausch ned!', '', '', '', '', 'Geh, Pepperl, plausch nicht!', '[{"kategorie": "wörtlich", "text": "Geh, Pepperl, schwatz nicht herum!  2. Geh, Pepperl, erzähl keinen Unsinn!  3. Geh, Pepperl, erzähl keine Märchen!"}]'::jsonb, ''),
  ('plausch-ned-pepal', 'Plausch ned, Pepal!', '', '', '', '', 'Plausch nicht, Pepperl!', '[{"kategorie": "wörtlich", "text": "Schwatz nicht herum, Pepperl!  2. Erzähl keinen Unsinn, Pepperl!  3. Erzähl keine Märchen, Pepperl!"}]'::jsonb, ''),
  ('da-ihaha-haassd-aa-pepihocka-waeura-domois-des-gaunze-ross-saumt-schwaaf-zaleegd-hod-und-ausn-rossschwaaf-daunn-a-buellicha-pepi-fiad-glotzadn-gmocht-wuan-is', 'Da Ihaha haassd aa ''Pepihocka'', wäura domois des gaunze Ross saumt Schwaaf zaleegd hod und ausn Rossschwaaf daunn a büllicha Pepi fiad Glotzadn gmocht wuan is!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Der Ihaha heißt auch ''Pepihacker'', weil er damals das ganze Ross samt Schweif zerlegt hat und aus dem Rossschweif dann ein billiger Pepi für die Glatzerten gemacht worden ist!', '[{"kategorie": "wörtlich", "text": "\"Der Pferdefleischhauer heißt auch ''Pepihacker'', weil er damals das ganze Ross samt Schweif zerlegt hat und aus dem Rossschweif dann eine billige Perücke für die Glatzerten gemacht worden ist!\"  2. Im Volksmund nannte man den Pferdemetzger einst ''Pepihacker'', denn er verwertete sogar den Schweif des Pferdes, der zur Perrücke der Hofgesellschaft wurde!  3. Den Pferdefleischhauer nannte man in Wien einst ''Pepihacker'', weil er das ganze Ross zerteilt hat – Schweif inklusive – und daraus gleich die nächste Billigperücke für die Halbglatzen gebaut wurde!"}]'::jsonb, ''),
  ('pea-grosskopfata-mit-wem-reedn', 'pea Großkopfata mit wem reedn', '', '', '', '', 'per Großkopferter mit jemandem reden', '[{"kategorie": "wörtlich", "text": "\"jemanden mit ''Großkopferter'' [Großkotz]  anreden\""}, {"kategorie": "", "text": "jemanden als \"Großkopferten\" [Großkotz] titulieren"}]'::jsonb, ''),
  ('reed-ned-pea-grosskopfata-mit-mia', 'Reed ned pea Großkopfata mit mia!', '', '', '', '', 'Rede nicht per Großkopferter mit mir!', '[{"kategorie": "wörtlich", "text": "\"Rede mich nicht als ''Großkopferter'' [Großkotz]  an!\"  2. Bezeichne mich nicht als ''Großkopferten'' [Großkotz]!  3. Nenne mich nicht ''Großkopferter'' [Großkotz]!"}]'::jsonb, ''),
  ('pest-in-doosn', 'Pest in Doosn', '', '', '', '', 'Pest in Dosen', '[{"kategorie": "wörtlich", "text": "\"konservierte Pest\" (vom lateinischen \"pestilentia\"=\"Seuche\")"}, {"kategorie": "scherzhaft für", "text": "Ekelpackung, Ekelmahlzeit, Ekelbüchse"}, {"kategorie": "fig., allg.", "text": "etwas Ekliges, Unappetitliches, Widerwärtiges"}]'::jsonb, ''),
